class Solution {
public:
    bool isPossible(vector<int>& nums) {
        unordered_map<int, int> count, endCount;
        for (int x : nums) count[x]++;
        for (int x : nums) {
            if (count[x] == 0) continue;
            if (endCount[x - 1] > 0) {
                endCount[x - 1]--;
                endCount[x]++;
                count[x]--;
            } else if (count[x + 1] > 0 && count[x + 2] > 0) {
                count[x]--;
                count[x + 1]--;
                count[x + 2]--;
                endCount[x + 2]++;
            } else {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean isPossible(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        Map<Integer, Integer> endCount = new HashMap<>();
        for (int x : nums) count.put(x, count.getOrDefault(x, 0) + 1);
        for (int x : nums) {
            if (count.get(x) == 0) continue;
            if (endCount.getOrDefault(x - 1, 0) > 0) {
                endCount.put(x - 1, endCount.get(x - 1) - 1);
                endCount.put(x, endCount.getOrDefault(x, 0) + 1);
                count.put(x, count.get(x) - 1);
            } else if (count.getOrDefault(x + 1, 0) > 0 && count.getOrDefault(x + 2, 0) > 0) {
                count.put(x, count.get(x) - 1);
                count.put(x + 1, count.get(x + 1) - 1);
                count.put(x + 2, count.get(x + 2) - 1);
                endCount.put(x + 2, endCount.getOrDefault(x + 2, 0) + 1);
            } else {
                return false;
            }
        }
        return true;
    }
}

